CREATE TABLE `Table_1` (
  `Câu hỏi Adhoc` VARCHAR(128) NOT NULL,
  `Tại sao lại chọn câu adhoc này` TEXT NOT NULL,
  `Câu query` TEXT NOT NULL,
  `Insight có được` TEXT NOT NULL
);

INSERT INTO `Table_1` (`Câu hỏi Adhoc`, `Tại sao lại chọn câu adhoc này`, `Câu query`, `Insight có được`) VALUES
  ('1. TOP 5 khách hàng chi tiêu nhiều nhất', 'Nhận diện các cá nhân đóng góp doanh thu lớn nhất để đưa vào chương trình chăm sóc VIP đặc biệt. Đưa ra những chương trình và phúc lợi tốt để thúc đẩy khách hàng trờ thành khách hàng độc quyền. Để có thể mua nhiều sản phẩm hơn. Bên cạnh đó các bộ phận như chăm sóc khách hàng hoặc kinh doanh sẽ đặc biệt tập trung hơn đối với những khách hàng là VIP này.', 'Select Top 5c.CustomerID,Concat_WS('' '',p.FirstName,p.MiddleName,p.LastName) As CustomerName,Count(soh.SalesOrderID) AS TotalOrders,Round(Sum(soh.TotalDue),2) As TotalSpentFrom Sales.Customer c JOIN Person.Person p ON c.PersonID = p.BusinessEntityIDJOIN Sales.SalesOrderHeader soh ON c.CustomerID = soh.CustomerIDGroup By C.CustomerID,P.FirstName,p.MiddleName,p.LastNameOrder By Round(Sum(soh.TotalDue),2) DESC', 'Insight có được: Top 5 khách hàng đều có mức chi tiêu trên 900 nghìn USD, phản ánh đây là nhóm khách hàng chiến lược có giá trị vòng đời (Customer Lifetime Value) rất cao.'),
  ('2. Top 5 Đại lý / Công ty Bán buôn (Store) Đóng góp Doanh thu Lớn nhất (Module Sales)', 'Xác định các đại lý chiến lược để có thể phân bổ nguồn lực chăm sóc đối tác hiệu quả. Bên cạnh đó xây dựng chính sách chiết khấu và thưởng doanh số.', 'SELECT TOP 5    s.BusinessEntityID AS StoreID,    s.Name AS StoreName,   COUNT(soh.SalesOrderID) AS TotalOrders,  ROUND(SUM(soh.TotalDue), 2) AS TotalRevenueFROM Sales.Store sJOIN Sales.Customer c ON s.BusinessEntityID = c.StoreIDJOIN Sales.SalesOrderHeader soh ON c.CustomerID = soh.CustomerIDGROUP BY s.BusinessEntityID, s.NameORDER BY TotalRevenue DESC;', 'Các đại lý lớn như Brakes and Gears,Excellent Riding Supplies,Vigorous Exercise Company,Totes & Baskets Company,Retail Mall,Đều đạt doanh thu từ 900,000$/ đại lý. Xác định được đây là đối tác quan trọng cần được ưu tiên duy trì và phát triển. Doanh thu cao không đến từ số lượng đơn hàng mà đến từ giá trị trung bình của mỗi đơn hàng. Điều này cho thấy AdventureWorks không phụ thuộc quá nhiều vào một đại lý duy nhất, giúp giảm rủi ro tập trung doanh thu.'),
  ('3. Lấy top 5 sản phẩm bán chạy nhất (theo số lượng)', 'Nhận diện các sản phẩm bán chạy nhất để đẩy mạnh hoạt động sản xuất, thương mại. Bên cạnh đó có thể phát triển được thị trường của các sản phẩm đó để tăng doanh thu của công ty', 'SELECT TOP 5      p.Name AS ProductName,      SUM(sod.OrderQty) AS TotalSold FROM Sales.SalesOrderDetail sod JOIN Production.Product p     ON sod.ProductID = p.ProductID GROUP BY p.Name ORDER BY TotalSold DESC', 'Đẩy mạnh việc sản xuất các sản phẩm bán chạy. Tăng cường kiểm soát chất lượng để bảo đảm được doanh thu của các sản phẩm bán chạy. Bên cạnh đó ra thêm nhiều mẫu mã để đa dạng hóa sản phẩm được bán chạy nhiều nhất.'),
  ('4. Danh mục Sản phẩm Có Doanh số Cao nhất.', 'Xác định danh mục sản phẩm nào đang là nguồn doanh thu chính của công ty. Doanh nghiệp Adventurework cần phải ưu tiên đầu tư sản xuất nhóm sản phẩm nào. Đưa ra cơ sở hợp lí để phân bổ ngân sách Marketing sản phẩm, quản lý tồn kho và lập kế hoạch nhập hàng, sản xuất', 'SELECT     pc.Name AS CategoryName,    SUM(sod.OrderQty) AS TotalQuantitySold,  ROUND(SUM(sod.LineTotal), 2) AS TotalSales,  ROUND(SUM(sod.LineTotal) * 100.0 / SUM(SUM(sod.LineTotal)) OVER(), 2) AS SalesSharePercentFROM Sales.SalesOrderDetail sodJOIN Production.Product p ON sod.ProductID = p.ProductIDJOIN Production.ProductSubcategory psc ON p.ProductSubcategoryID = p.ProductSubcategoryIDJOIN Production.ProductCategory pc ON psc.ProductCategoryID = pc.ProductCategoryIDGROUP BY pc.NameORDER BY TotalSales DESC;', 'Đây là danh mục đóng góp doanh thu lớn nhất trong AdventureWorks, cho thấy nhu cầu về linh kiện và phụ tùng xe đạp rất cao. Components có thể được xem là dòng sản phẩm cốt lõi của doanh nghiệp.'),
  ('5. Top 5 nhà cung cấp có tỷ lệ hàng bị từ chối cao nhất.', 'Kiểm tra tỷ lệ giao hàng bị trả lại (Rejected) của các nhà cung cấp linh kiện/nguyên vật liệu.', 'SELECT TOP 5    v.BusinessEntityID AS VendorID,    v.Name AS VendorName, COUNT(DISTINCT(poh.PurchaseOrderID)) AS TotalOrders,    SUM(pod.ReceivedQty) AS TotalReceived,    SUM(pod.RejectedQty) AS TotalRejected, ROUND(SUM(pod.RejectedQty) * 100.0 / NULLIF(SUM(pod.ReceivedQty), 0), 2) AS RejectRatePercentFROM Purchasing.Vendor vJOIN Purchasing.PurchaseOrderHeader poh     ON v.BusinessEntityID = poh.VendorIDJOIN Purchasing.PurchaseOrderDetail pod     ON poh.PurchaseOrderID = pod.PurchaseOrderIDGROUP BY v.BusinessEntityID, v.NameHAVING SUM(pod.RejectedQty) > 0ORDER BY RejectRatePercent DESC;', 'Các Vendor trong Top 5 đều có Reject Rate dao động từ 5.33% đến 5.88%.  Không có một Vendor nào vượt trội về mức độ lỗi, điều này cho thấy chất lượng giữa các nhà cung cấp tương đối đồng đều. Tuy nhiên, mức khoảng 5% vẫn là tỷ lệ đáng chú ý nếu doanh nghiệp hướng tới tiêu chuẩn chất lượng cao.'),
  ('6. Hiệu suất bán hàng của từng nhân viên  như thế nào so với chỉ tiêu doanh số', 'Đánh giá mức độ hoàn thành của từng nhân viên kinh doanh. Xác định những nhân viên có hiệu suất vượt trội để khen thưởng đúng với năng lực. Đối với những nhân viên chưa đạt được KPI thì cần có kế hoạch đào tạo hoặc hỗ trợ hợp lí. Đánh giá và so sánh việc phân bổ Sales Quota giữa các khu vực', 'SELECT     sp.BusinessEntityID AS SalesPersonID,    p.FirstName + '' '' + p.LastName AS SalesPersonName,    st.Name AS TerritoryName,    sp.SalesQuota,    sp.SalesYTD AS SalesYTD,    (sp.SalesYTD - sp.SalesQuota) / NULLIF(sp.SalesQuota, 0) * 100 AS Quota Achievement PercentFROM Sales.SalesPerson spJOIN Person.Person p     ON sp.BusinessEntityID = p.BusinessEntityIDLEFT JOIN Sales.SalesTerritory st     ON sp.TerritoryID = st.TerritoryIDORDER BY SalesYTD DESC;', 'Đánh giá được năng lực của từng nhân viên kinh doanh để được ra thưởng và kế hoạch đào tạo hợp lí để tăng hiệu suất làm việc của bộ phận kinh doanh. Xác định được nhân viên kinh doanh vượt trội để đề xuất lên cấp bậc quản lý.Cần rà soát và xây dựng lại khung chỉ tiêu bán hàng để phù hợp với từng cấp bậc của nhân viên kinh doanh để tránh việc làm giảm kỳ vọng của nhân viên kinh doanh khi không bán được hàng'),
  ('7. So sánh hiệu quả bán hàng của kênh Online và Offline', 'Đánh giá được sự hiệu quả của việc kinh doanh Online và Offline để đưa ra chiến lược kinh doanh hợp lý với từng kênh', 'SELECT     CASE         WHEN OnlineOrderFlag = 1 THEN ''Online (B2C)''         ELSE ''Offline / Store (B2B)''     END AS SalesChannel,    COUNT(SalesOrderID) AS TotalOrders,    ROUND(SUM(TotalDue), 2) AS TotalRevenue,    ROUND(AVG(TotalDue), 2) AS AverageOrderValueFROM Sales.SalesOrderHeaderGROUP BY OnlineOrderFlag;', 'Kênh Online đạt số lượng đơn hàng rất lớn (chiếm 60% tổng số đơn) nhưng chỉ mang lại ~20% doanh thu do đơn hàng nhỏ lẻ. Kênh Offline mang lại 80% doanh thu tổng.'),
  ('8.Danh sách Khách hàng Mua hàng Lần cuối Đã Qua 1 Năm', 'Phát hiện các khách hàng có nguy cơ ngưng sử dụng dịch vụ để thực hiện chiến dịch Re-engagement.', 'WITH LastOrder AS (    SELECT         CustomerID,        MAX(OrderDate) AS MostRecentOrder    FROM Sales.SalesOrderHeader    GROUP BY CustomerID)SELECT     CustomerID,    MostRecentOrder,    DATEDIFF(day, MostRecentOrder, ''2014-06-30'') AS DaysSinceLastOrderFROM LastOrderWHERE DATEDIFF(day, MostRecentOrder, ''2014-06-30'') > 365ORDER BY DaysSinceLastOrder DESC;', 'Giảm chi phí tìm kiếm khách hàng mới, vì chi phí giữ chân khách hàng cũ thường thấp hơn.Kết quả truy vấn cho thấy có 1.016 khách hàng không phát sinh đơn hàng trong hơn 365 ngày. Đây là một nhóm khách hàng có nguy cơ rời bỏ rất cao nếu doanh nghiệp không có các hoạt động chăm sóc hoặc tái kích hoạt.');

-- ----------------------------------------
-- Table: Table_2
-- Rows: 3
-- ----------------------------------------

CREATE TABLE `Table_2` (
  `Chỉ số KPI` VARCHAR(87) NOT NULL,
  `Diễn giải công thức bằng lời` VARCHAR(255) NOT NULL,
  `Tại sao lại chọn chỉ số này` VARCHAR(128) NOT NULL,
  `Câu query` TEXT NOT NULL,
  `Insight có được` VARCHAR(255) NOT NULL
);

INSERT INTO `Table_2` (`Chỉ số KPI`, `Diễn giải công thức bằng lời`, `Tại sao lại chọn chỉ số này`, `Câu query`, `Insight có được`) VALUES
  ('1. Lợi Nhuận Gộp Theo Năm', '- Lợi Nhuận Gộp = Doanh Thu Bán Hàng - Tổng Giá Vốn Bán Hàng. Tỷ suất Lợi Nhuận Gộp (%) = (Lợi Nhuận Gộp / Doanh Thu) * 100.', 'Để đo lường hiệu quả quản lý chi phí sản xuất/vốn hàng bán của sản phẩm.', 'SELECT   YEAR(soh.OrderDate) AS OrderYear,    SUM(sod.LineTotal) AS TotalRevenue,    SUM(p.StandardCost * sod.OrderQty) AS TotalCOGS,  SUM(sod.LineTotal) - SUM(p.StandardCost * sod.OrderQty) AS GrossProfit,    (SUM(sod.LineTotal) - SUM(p.StandardCost * sod.OrderQty)) * 100.0 / SUM(sod.LineTotal) AS GrossMarginPercentFROM Sales.SalesOrderHeader sohJOIN Sales.SalesOrderDetail sod     ON soh.SalesOrderID = sod.SalesOrderIDJOIN Production.Product p     ON sod.ProductID = p.ProductIDGROUP BY YEAR(soh.OrderDate)ORDER BY OrderYear;', 'Công ty AdventureWorks mở rộng hoạt động kinh doanh rất tốt trong giai đoạn 2011–2013 và nhu cầu thị trường tăng trưởng tích cực. Ở năm 2012 là năm doanh nghiệp hoạt động kém hiệu quả nhất về lợi nhuận.'),
  ('2. Giá Trị Đơn Hàng Trung Bình (Average Order Value - AOV)', 'Tổng Doanh Thu / Tổng Số Đơn Hàng Phân Theo Kênh.', 'Đo lường quy mô trung bình của một đơn hàng để áp dụng chiến lược Up-sell/Cross-sell.', 'SELECT     YEAR(OrderDate) AS OrderYear,    CASE WHEN OnlineOrderFlag = 1 THEN ''Online'' ELSE ''Store'' END AS Channel,    COUNT(SalesOrderID) AS TotalOrders,    SUM(TotalDue) AS TotalRevenue,    SUM(TotalDue) / COUNT(SalesOrderID) AS AOVFROM Sales.SalesOrderHeaderGROUP BY YEAR(OrderDate), OnlineOrderFlagORDER BY OrderYear, Channel', 'Điều này cho thấy khách hàng mua trực tiếp thường có xu hướng mua nhiều sản phẩm hoặc lựa chọn các sản phẩm có giá trị cao hơn trong mỗi đơn hàng. Doanh nghiệp đã thu hút được nhiều khách hàng Online hơn nhưng mỗi đơn hàng lại có giá trị nhỏ hơn.'),
  ('3.Tỷ Lệ Đơn Hàng Giao Trễ (Late Shipping Rate)', 'Tỷ lệ giao trễ (%) = (Số đơn có ShipDate > DueDate / Tổng số đơn) * 100.', 'Đánh giá hiệu quả vận hành chuỗi cung ứng và sự hài lòng của khách hàng', 'SELECT     YEAR(OrderDate) AS OrderYear,    COUNT(SalesOrderID) AS TotalOrders,    SUM(CASE WHEN ShipDate > DueDate THEN 1 ELSE 0 END) AS LateOrders,    SUM(CASE WHEN ShipDate > DueDate THEN 1 ELSE 0 END) * 100.0 / COUNT(SalesOrderID) AS LateShippingRatePercentFROM Sales.SalesOrderHeaderGROUP BY YEAR(OrderDate)ORDER BY OrderYear;', 'Tỷ lệ giao trễ duy trì ở mức 0% trong hệ thống, chứng tỏ năng lực vận chuyển đáp ứng rất tốt.');